        })}
        <div className="flex-1" />
        <div title={app?.user.name} className="mb-2 grid h-8 w-8 place-items-center rounded-full bg-slate-800 text-xs font-semibold text-slate-200">{initials(s(app?.user.name))}</div>
        <button aria-label="Sign out" title="Sign out" onClick={() => app?.auth.signOut()} className="grid h-11 w-11 place-items-center rounded-lg text-slate-400 transition-colors hover:bg-white/5 hover:text-slate-200">
          <LogOut size={18} aria-hidden="true" />
        </button>
      </aside>
      <header className="sticky top-0 z-30 flex h-14 items-center justify-between border-b border-slate-200 bg-white px-4 lg:hidden">
