        <nav className="fixed inset-x-0 bottom-0 z-30 flex border-t border-slate-200 bg-white pb-[env(safe-area-inset-bottom)] lg:hidden">
          {items.map((it) => {
            const on = it.k === active;
            return (
              <button key={it.k} onClick={() => app?.navigate(it.to)} aria-current={on ? "page" : undefined} className={"flex h-16 flex-1 flex-col items-center justify-center gap-1 text-xs font-medium " + (on ? "text-sky-800" : "text-slate-600")}>
                <it.icon size={20} aria-hidden="true" />
