        {action}
      </div>
      {children}
    </motion.section>
  );
}

export default function LeadDashboard({ app }: Props) {
  const [now, setNow] = useState(0);
  useEffect(() => {
    setNow(Date.now());
    const t = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(t);
  }, []);
  useEffect(() => {
    if (!app) return;
    const us = [app.live("ticket"), app.live("message")];
    return () => us.forEach((u) => u());
  }, [app]);

  const tickets: R[] = app ? (app.rows("ticket") as R[]) : [];
  const agents: R[] = app ? (app.rows("agent") as R[]) : [];
  const customers: R[] = app ? (app.rows("customer") as R[]) : [];
  const messages: R[] = app ? (app.rows("message") as R[]) : [];
  const loading = app ? app.loading("ticket") : false;

  const d = useMemo(() => {
    const openList = tickets.filter((t) => s(t.status) !== "solved");
    const byStatus = STATUSES.map((x) => ({ ...x, v: tickets.filter((t) => (s(t.status) || "new") === x.k).length }));
    const byPri = PRIS.map((x) => ({ ...x, v: openList.filter((t) => (s(t.priority) || "normal") === x.k).length }));
    const attention = openList
      .map((t) => ({ t, i: slaInfo(t, now) }))
      .filter((x) => x.i.level === "red" || x.i.level === "amber" || x.t.escalated === true)
      .sort((a, b) => a.i.ms - b.i.ms);
    const overdue = attention.filter((x) => x.i.level === "red").length;
    const rated = tickets.filter((t) => Number(t.csat) > 0);
    const avg = rated.length ? rated.reduce((a, t) => a + Number(t.csat), 0) / rated.length : 0;
    const dist = [5, 4, 3, 2, 1].map((n) => ({ n, v: rated.filter((t) => Number(t.csat) === n).length }));
    const comments = rated
      .filter((t) => s(t.csat_comment))
      .sort((a, b) => s(b.updated_at).localeCompare(s(a.updated_at)))
      .slice(0, 3);
    const firsts: number[] = [];
    for (const t of tickets) {
      const replies = messages
        .filter((m) => s(m.ticket_id) === s(t.id) && s(m.author_role) === "agent")
        .map((m) => new Date(s(m.at) || s(m.created_at)).getTime())
        .filter((x) => x > 0)
        .sort((a, b) => a - b);
      const c = new Date(s(t.created_at)).getTime();
      if (replies.length && c && replies[0] >= c) firsts.push(replies[0] - c);
    }
    firsts.sort((a, b) => a - b);
    const median = firsts.length ? firsts[Math.floor(firsts.length / 2)] : 0;
    const start = now ? new Date(new Date(now).toDateString()).getTime() - 6 * DAY : 0;
    const fmt = new Intl.DateTimeFormat("en-GB", { weekday: "short", day: "numeric" });
    const week = now
      ? Array.from({ length: 7 }, (_, i) => {
          const a = start + i * DAY;
          const inDay = (iso: string) => {
            const x = new Date(iso).getTime();
            return x >= a && x < a + DAY;
          };
          return {
            day: i === 6 ? "Today" : fmt.format(new Date(a)),
            Opened: tickets.filter((t) => inDay(s(t.created_at))).length,
            Solved: tickets.filter((t) => s(t.status) === "solved" && inDay(s(t.updated_at))).length,
          };
        })
      : [];
    const load = agents
      .map((a) => {
        const mine = tickets.filter((t) => s(t.assignee_id) === s(a.id));
        const r = mine.filter((t) => Number(t.csat) > 0);
        return {
          id: s(a.id),
          name: s(a.name),
          open: mine.filter((t) => s(t.status) !== "solved").length,
          late: mine.filter((t) => s(t.status) !== "solved" && slaInfo(t, now).level === "red").length,
          solved: mine.filter((t) => s(t.status) === "solved").length,
          csat: r.length ? r.reduce((x, t) => x + Number(t.csat), 0) / r.length : 0,
        };
      })
      .sort((a, b) => b.open - a.open);
    return { openList, byStatus, byPri, attention, overdue, rated, avg, dist, comments, median, week, load, unassigned: openList.filter((t) => !s(t.assignee_id)).length };
  }, [tickets, agents, messages, now]);

  const first = s(app?.user.name).split(" ")[0];
  const today = now ? new Intl.DateTimeFormat("en-GB", { weekday: "long", day: "numeric", month: "long" }).format(new Date(now)) : "";
  const maxDist = Math.max(1, ...d.dist.map((x) => x.v));
  const maxLoad = Math.max(1, ...d.load.map((x) => x.open));
  const custName = (t: R) => s(customers.find((c) => s(c.id) === s(t.customer_id))?.name) || s(t.from) || "Unknown sender";
  const agentName = (t: R) => s(agents.find((a) => s(a.id) === s(t.assignee_id))?.name);
  const empty = !loading && tickets.length === 0;
  const busy = loading && tickets.length === 0;

  const kpis = [
    { l: "Open tickets", v: String(d.openList.length), hint: d.unassigned + " unassigned", tone: "text-slate-900" },
    { l: "Overdue", v: String(d.overdue), hint: d.overdue ? "Past their SLA right now" : "Every ticket is inside its SLA", tone: d.overdue ? "text-rose-700" : "text-slate-900" },
    { l: "Median first reply", v: d.median ? dur(d.median) : "–", hint: "Time to the first agent reply", tone: "text-slate-900" },
    { l: "Customer satisfaction", v: d.rated.length ? d.avg.toFixed(1) : "–", hint: d.rated.length ? "out of 5 · " + d.rated.length + " ratings" : "No ratings yet", tone: "text-slate-900" },
  ];

  return (
    <Shell app={app} active="dash">
      <main className="mx-auto max-w-[1320px] px-4 pb-24 pt-6 lg:px-8 lg:pb-12 lg:pt-8">
        <div className="mb-6 flex flex-col gap-1 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <h1 className="text-2xl font-semibold tracking-tight sm:text-[28px]">Desk health</h1>
            <p className="mt-1 text-sm text-slate-600">{first ? first + ", here's" : "Here's"} how the team is tracking against its SLAs{today ? " on " + today : ""}.</p>
          </div>
          <button onClick={() => app?.navigate("/inbox")} className="mt-3 inline-flex h-10 items-center gap-1.5 self-start rounded-lg bg-sky-700 px-4 text-sm font-semibold text-white transition-colors hover:bg-sky-800 sm:mt-0 sm:self-auto">
            Open the queue <ArrowRight size={15} aria-hidden="true" />
          </button>
        </div>

        <dl className="grid grid-cols-2 overflow-hidden rounded-xl border border-slate-200 bg-white lg:grid-cols-4">
          {kpis.map((k, i) => (
            <div key={k.l} className={"px-4 py-4 sm:px-5 " + (i % 2 ? "border-l border-slate-200 " : "") + (i > 1 ? "border-t border-slate-200 lg:border-t-0 " : "") + (i === 2 ? "lg:border-l" : "")}>
              <dt className="text-xs font-medium text-slate-600 sm:text-sm">{k.l}</dt>
              <dd className={"mt-1 text-2xl font-semibold tabular-nums tracking-tight sm:text-[28px] " + k.tone}>{busy ? <span className="inline-block h-7 w-12 animate-pulse rounded bg-slate-200 align-middle" /> : k.v}</dd>
              <dd className="mt-0.5 text-xs text-slate-600">{busy ? "" : k.hint}</dd>
            </div>
          ))}
        </dl>

        {empty && (
          <div className="mt-4 rounded-xl border border-dashed border-slate-300 bg-white px-6 py-10 text-center">
            <div className="font-semibold">No tickets yet</div>
            <p className="mx-auto mt-1 max-w-sm text-sm text-slate-600">When customers write in by email or through the help centre, volume, SLAs and ratings show up here.</p>
          </div>
        )}

        <div className="mt-4 grid gap-4 lg:grid-cols-3">
          <Panel title="Needs attention" i={1} className="lg:col-span-2" action={<span className="text-xs text-slate-600">{d.attention.length} ticket{d.attention.length === 1 ? "" : "s"} overdue or due within 2 h</span>}>
            {busy ? (
              <div className="space-y-3 p-5">{[0, 1, 2].map((i) => <div key={i} className="h-4 animate-pulse rounded bg-slate-100" />)}</div>
            ) : d.attention.length === 0 ? (
              <div className="flex items-center gap-3 px-5 py-8 text-sm text-slate-700">
                <CheckCircle size={20} className="shrink-0 text-emerald-600" aria-hidden="true" />
                Nothing is close to breaching. The next SLA is more than two hours away.
              </div>
            ) : (
              <ul className="divide-y divide-slate-100">
                {d.attention.slice(0, 6).map(({ t, i }) => (
                  <li key={s(t.id)}>
                    <button onClick={() => app?.navigate("/inbox")} className="flex w-full flex-col gap-1.5 px-5 py-3 text-left transition-colors hover:bg-slate-50 sm:flex-row sm:items-center sm:gap-4">
                      <div className="min-w-0 flex-1">
                        <div className="truncate text-sm font-medium text-slate-900">{s(t.subject)}</div>
                        <div className="truncate text-xs text-slate-600">
                          {custName(t)} · {agentName(t) ? agentName(t) : <span className="font-medium text-amber-800">Unassigned</span>}
                        </div>
                      </div>
                      <span className={"inline-flex shrink-0 items-center gap-1 self-start rounded-md px-1.5 py-0.5 text-xs font-medium tabular-nums sm:self-auto " + i.cls}>
                        {i.level === "red" ? <AlertTriangle size={12} aria-hidden="true" /> : <Clock size={12} aria-hidden="true" />}
                        {i.label}
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </Panel>

          <Panel title="Open by priority" i={2}>
            <div className="px-5 py-4">
              <div className="mb-4 flex h-2.5 overflow-hidden rounded-full bg-slate-100" role="img" aria-label={d.byPri.map((x) => x.l + " " + x.v).join(", ")}>
                {d.byPri.map((x) => (d.openList.length ? <div key={x.k} className={x.c} style={{ width: (x.v / d.openList.length) * 100 + "%" }} /> : null))}
              </div>
              <ul className="space-y-2.5">
                {d.byPri.map((x) => (
                  <li key={x.k} className="flex items-center justify-between text-sm">
                    <span className="flex items-center gap-2 text-slate-700">
                      <span className={"h-2 w-2 rounded-full " + x.c} />
                      {x.l}
                    </span>
                    <span className="font-semibold tabular-nums">{x.v}</span>
                  </li>
                ))}
              </ul>
              <div className="mt-5 border-t border-slate-100 pt-4">
                <div className="mb-2 text-xs font-medium text-slate-600">All tickets by status</div>
                <ul className="grid grid-cols-2 gap-x-4 gap-y-2">
                  {d.byStatus.map((x) => (
                    <li key={x.k} className="flex items-center justify-between text-sm">
                      <span className="flex items-center gap-2 text-slate-700">
                        <span className="h-2 w-2 rounded-full" style={{ background: x.c }} />
                        {x.l}
                      </span>
                      <span className="font-semibold tabular-nums">{x.v}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </Panel>

          <Panel title="Last 7 days" i={3} className="lg:col-span-2" action={
            <div className="flex items-center gap-3 text-xs text-slate-600">
              <span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-sm bg-sky-600" />Opened</span>
              <span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-sm bg-emerald-500" />Solved</span>
            </div>
          }>
            <div className="h-[240px] px-2 py-4 sm:px-4">
              {d.week.length ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={d.week} barGap={3} margin={{ top: 4, right: 8, left: -18, bottom: 0 }}>
                    <CartesianGrid vertical={false} stroke="#e2e8f0" />
                    <XAxis dataKey="day" tickLine={false} axisLine={false} tick={{ fontSize: 12, fill: "#475569" }} />
                    <YAxis allowDecimals={false} tickLine={false} axisLine={false} tick={{ fontSize: 12, fill: "#475569" }} />
                    <Tooltip cursor={{ fill: "#f1f5f9" }} contentStyle={{ borderRadius: 8, border: "1px solid #e2e8f0", fontSize: 13 }} />
                    <Bar dataKey="Opened" fill="#0284c7" radius={[3, 3, 0, 0]} maxBarSize={22} />
                    <Bar dataKey="Solved" fill="#10b981" radius={[3, 3, 0, 0]} maxBarSize={22} />
                  </BarChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full animate-pulse rounded-lg bg-slate-100" />
              )}
            </div>
          </Panel>

          <Panel title="Customer satisfaction" i={4} action={
            <span className="flex items-center gap-1 text-sm font-semibold tabular-nums">
              <Star size={15} className="fill-amber-400 text-amber-500" aria-hidden="true" /> {d.rated.length ? d.avg.toFixed(1) : "–"}
            </span>
          }>
            <div className="px-5 py-4">
              <ul className="space-y-1.5">
                {d.dist.map((x) => (
                  <li key={x.n} className="flex items-center gap-2.5 text-xs">
                    <span className="w-12 text-slate-700">{x.n} star{x.n > 1 ? "s" : ""}</span>
                    <div className="h-2 flex-1 overflow-hidden rounded-full bg-slate-100">
                      <div className="h-full rounded-full bg-amber-400" style={{ width: (x.v / maxDist) * 100 + "%" }} />
                    </div>
                    <span className="w-5 text-right font-medium tabular-nums text-slate-700">{x.v}</span>
                  </li>
                ))}
              </ul>
              <div className="mt-4 space-y-3 border-t border-slate-100 pt-4">
                {d.comments.length === 0 && <p className="text-sm text-slate-600">Comments from ratings appear here.</p>}
                {d.comments.map((t) => (
                  <figure key={s(t.id)} className="text-sm">
                    <blockquote className="text-slate-800">“{s(t.csat_comment)}”</blockquote>
                    <figcaption className="mt-0.5 text-xs text-slate-600">{custName(t)} · {s(t.csat)} of 5</figcaption>
                  </figure>
                ))}
              </div>
            </div>
          </Panel>

          <Panel title="Agent workload" i={5} className="lg:col-span-3">
            {d.load.length === 0 ? (
              <p className="px-5 py-6 text-sm text-slate-600">No agents yet. Add people from Team & access to start assigning tickets.</p>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full min-w-[560px] text-sm">
                  <thead>
                    <tr className="text-left text-xs text-slate-600">
                      <th className="px-5 py-2.5 font-medium">Agent</th>
                      <th className="px-3 py-2.5 font-medium">Open</th>
                      <th className="hidden px-3 py-2.5 font-medium sm:table-cell">Load</th>
                      <th className="px-3 py-2.5 text-right font-medium">Overdue</th>
                      <th className="px-3 py-2.5 text-right font-medium">Solved</th>
                      <th className="px-5 py-2.5 text-right font-medium">CSAT</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 border-t border-slate-100">
                    {d.load.map((a) => (
                      <tr key={a.id}>
                        <td className="px-5 py-3">
                          <div className="flex items-center gap-2.5">
                            <span className="grid h-7 w-7 place-items-center rounded-full bg-slate-800 text-[11px] font-semibold text-white">{initials(a.name)}</span>
                            <span className="font-medium">{a.name}</span>
                          </div>
                        </td>
                        <td className="px-3 py-3 font-semibold tabular-nums">{a.open}</td>
                        <td className="hidden w-[30%] px-3 py-3 sm:table-cell">
                          <div className="h-2 overflow-hidden rounded-full bg-slate-100">
                            <div className="h-full rounded-full bg-sky-600" style={{ width: (a.open / maxLoad) * 100 + "%" }} />
                          </div>
                        </td>
                        <td className={"px-3 py-3 text-right tabular-nums " + (a.late ? "font-semibold text-rose-700" : "text-slate-700")}>{a.late}</td>
                        <td className="px-3 py-3 text-right tabular-nums text-slate-700">{a.solved}</td>
                        <td className="px-5 py-3 text-right tabular-nums text-slate-700">{a.csat ? a.csat.toFixed(1) : "–"}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </Panel>
        </div>
      </main>
    </Shell>
  );
}

