const hours: Record<string, number> = { urgent: 1, high: 4, normal: 8, low: 24 };
const pr = row.priority ? String(row.priority) : 'normal';
const patch: Record<string, unknown> = {};
if (!row.priority) patch.priority = 'normal';
if (!row.category) patch.category = 'other';
if (!row.status) patch.status = 'new';
if (!row.sla_due) patch.sla_due = new Date(ctx.now().getTime() + (hours[pr] || 8) * 3600000).toISOString();
if (Object.keys(patch).length) await ctx.db.update('ticket', String(row.id), patch);
ctx.notify({ title: 'New ticket: ' + String(row.subject), body: pr + ' priority', role: 'agent' });

const next: Record<string, string> = { low: 'normal', normal: 'high', high: 'urgent', urgent: 'urgent' };
const now = ctx.now().getTime();
const tickets = await ctx.db.list('ticket');
let n = 0;
for (const t of tickets) {
  if (String(t.status) === 'solved' || t.escalated === true || !t.sla_due) continue;
  if (new Date(String(t.sla_due)).getTime() >= now) continue;
  const pr = next[String(t.priority || 'normal')] || 'high';
  await ctx.db.update('ticket', String(t.id), { escalated: true, priority: pr });
  ctx.notify({ title: 'SLA breached: ' + String(t.subject), body: 'Escalated to ' + pr + ' priority', role: 'lead' });
  n++;
}
ctx.log('escalated ' + n);
